SELECT toString(cohort) AS cohort_week, count() AS users,
       if(cohort + INTERVAL 1 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 1 WEEK)) / count(), 1), NULL) AS week_1,
       if(cohort + INTERVAL 2 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 2 WEEK)) / count(), 1), NULL) AS week_2,
       if(cohort + INTERVAL 3 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 3 WEEK)) / count(), 1), NULL) AS week_3,
       if(cohort + INTERVAL 4 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 4 WEEK)) / count(), 1), NULL) AS week_4,
       if(cohort + INTERVAL 5 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 5 WEEK)) / count(), 1), NULL) AS week_5,
       if(cohort + INTERVAL 6 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 6 WEEK)) / count(), 1), NULL) AS week_6,
       if(cohort + INTERVAL 7 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 7 WEEK)) / count(), 1), NULL) AS week_7,
       if(cohort + INTERVAL 8 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 8 WEEK)) / count(), 1), NULL) AS week_8,
       if(cohort + INTERVAL 9 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 9 WEEK)) / count(), 1), NULL) AS week_9,
       if(cohort + INTERVAL 10 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 10 WEEK)) / count(), 1), NULL) AS week_10,
       if(cohort + INTERVAL 11 WEEK <= toMonday({to:DateTime64(9)}), round(100 * countIf(has(weeks, cohort + INTERVAL 11 WEEK)) / count(), 1), NULL) AS week_11
FROM (
    SELECT UserId, min(week) AS cohort, groupUniqArray(week) AS weeks
    FROM (
        SELECT UserId, toMonday(Timestamp) AS week
        FROM product_events
        WHERE UserId != '' AND Timestamp >= {to:DateTime64(9)} - INTERVAL 90 DAY AND Timestamp < {to:DateTime64(9)} AND (empty({env_ids:Array(String)}) OR has({env_ids:Array(String)}, EnvId)) AND (empty({services:Array(String)}) OR has({services:Array(String)}, ServiceName))
    )
    GROUP BY UserId
)
WHERE cohort >= toMonday({to:DateTime64(9)}) - INTERVAL 11 WEEK
GROUP BY cohort ORDER BY cohort
